#[derive(Debug, Clone, PartialEq, Default)]
pub struct WeightCal {
    pub factory_g: u32,
    pub dac: Vec<i32>,
    pub cell50: Vec<i32>,
    pub cell100: Vec<i32>,
    pub cell150: Vec<i32>,
}

impl WppObjectCodec for WeightCal {
    const TYPE_ID: u16 = 524;
    const TYPE_NAME: &'static str = "TYPE_WEIGHT_CAL";
    const CLASS_NAME: &'static str = "WeightCal";
    const FIXED_DATA_SIZE: Option<usize> = Some(72);

    fn data_size(&self) -> usize {
        core::cmp::max(
            8 + self.dac.len() * 4
                + self.cell50.len() * 4
                + self.cell100.len() * 4
                + self.cell150.len() * 4,
            72,
        )
    }

    fn parse(r: &mut Reader<'_>) -> Result<Self, ParseError> {
        Ok(Self {
            factory_g: r.u32()?,
            dac: r.array_i32()?,
            cell50: r.array_i32()?,
            cell100: r.array_i32()?,
            cell150: r.array_i32()?,
        })
    }

    fn write(&self, w: &mut Writer) {
        let start = w.len();
        w.u32(self.factory_g);
        w.array_i32(&self.dac);
        w.array_i32(&self.cell50);
        w.array_i32(&self.cell100);
        w.array_i32(&self.cell150);
        w.pad_to(start + self.data_size());
    }
}

