/// Names for type ids the app declares but has no object class for.
pub fn type_name_for_id(type_id: u16) -> Option<&'static str> {
    match type_id {
        0 => Some("TYPE_WIFI_ENABLE_FALSE"),
        1 => Some("TYPE_WIFI_ENABLE_TRUE"),
        2 => Some("TYPE_THRESHOLD_HR_LOW"),
        3 => Some("TYPE_THRESHOLD_TEMPERATURE_HIGH"),
        4 => Some("TYPE_WAKEUP"),
        5 => Some("TYPE_RETAIL"),
        6 => Some("TYPE_MEDIA"),
        7 => Some("TYPE_LULLABY"),
        275 => Some("TYPE_SKIP_ASSOC"),
        1042 => Some("TYPE_NETUPDATE_REBOOT"),
        1294 => Some("TYPE_HANDS_CAL_START"),
        1295 => Some("TYPE_HANDS_CAL_STOP"),
        2064 => Some("TYPE_WSM_VASISTAS_HEAD"),
        2065 => Some("TYPE_WSM_VASISTAS_DURATION"),
        65527 => Some("TYPE_CMDERROR_ERR_ARG_NOT_SET"),
        65528 => Some("TYPE_CMDERROR_ERR_ARG_INVAL"),
        65529 => Some("TYPE_CMDERROR_ERR_BAD_VERSION"),
        65530 => Some("TYPE_CMDERROR_ERR_AUTH_ERR"),
        65531 => Some("TYPE_CMDERROR_ERR_NOT_AUTH"),
        65532 => Some("TYPE_CMDERROR_ERR_CMDINVAL"),
        65533 => Some("TYPE_CMDERROR_ERR_CMDUNKN"),
        65534 => Some("TYPE_IFSTATE_ERR_UNKNOWNIF"),
        65535 => Some("TYPE_IFSTATE_ERR_FAIL"),
        _ => None,
    }
}
